{
  "schemaVersion": "0.3.0-alpha",
  "programId": "three-isolates-selective-media",
  "name": "Streak three isolates, read the plates, subculture and Gram stain",
  "description": "Three overnight broths streaked for single colonies on selective agar, 37 °C incubation, morning readings, supervisor sign-off, purity plate and a Gram stain. One loop station, one incubator shelf that holds two plates (the third plate waits on the bench until a shelf slot frees), one staining rack, one microscope, one technician and one supervisor. The incubate step is replicated three times with maxInFlight 2 so plate 3 is held at room temperature instead of being stranded on a full shelf; in practice instance 1 and 2 run 16-20 h overnight and instance 3 runs 6 h (the duration is variable, so set the third timer to 6 h at the bench).",
  "environmentType": "laboratory",
  "actors": 1,
  "tracks": [
    {
      "trackId": "t-bench",
      "name": "Streaking bench / loop station",
      "steps": [
        {
          "stepId": "wipe-bench",
          "name": "Wipe bench with 70 % ethanol and light the burner",
          "task": "bench",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "programStart" }
        },
        {
          "stepId": "label-plates",
          "name": "Label three selective plates (isolate number, medium, date)",
          "task": "bench",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "afterStep", "stepId": "wipe-bench" }
        },
        {
          "stepId": "streak-isolate",
          "name": "Streak isolate for single colonies in four quadrants, flaming the loop between each",
          "task": "loopStation",
          "duration": { "type": "fixed", "seconds": 600 },
          "replicates": { "count": 3, "mode": "serial" },
          "startTrigger": { "type": "afterStep", "stepId": "label-plates" }
        },
        {
          "stepId": "incubate-plate",
          "name": "Incubate plate inverted at 37 °C (shelf holds two plates)",
          "task": "incubator",
          "duration": {
            "type": "variable",
            "minSeconds": 21600,
            "maxSeconds": 72000,
            "defaultSeconds": 57600
          },
          "replicates": { "count": 3, "mode": "parallel", "maxInFlight": 2 },
          "startTrigger": { "type": "afterStep", "stepId": "streak-isolate", "instances": "each" }
        },
        {
          "stepId": "read-plate",
          "name": "Read plate: count colonies, note colour and selective growth",
          "task": "supervisor",
          "duration": { "type": "fixed", "seconds": 900 },
          "startTrigger": { "type": "afterStep", "stepId": "incubate-plate", "instances": "each" }
        },
        {
          "stepId": "pick-colony",
          "name": "Pick a single well-separated colony into fresh broth",
          "task": "loopStation",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "afterStep", "stepId": "read-plate", "instances": "each" }
        }
      ]
    },
    {
      "trackId": "t-purity",
      "name": "Subculture / purity plate",
      "steps": [
        {
          "stepId": "readings-signoff",
          "name": "Supervisor signs off the readings",
          "task": "supervisor",
          "duration": { "type": "fixed", "seconds": 300 },
          "startTrigger": { "type": "afterStep", "stepId": "pick-colony", "instances": "all" }
        },
        {
          "stepId": "streak-purity-plate",
          "name": "Streak the purity plate (only after sign-off)",
          "task": "loopStation",
          "duration": { "type": "fixed", "seconds": 900 },
          "startTrigger": { "type": "afterStep", "stepId": "readings-signoff" }
        },
        {
          "stepId": "incubate-purity-plate",
          "name": "Incubate the purity plate at 37 °C",
          "task": "incubator",
          "duration": { "type": "fixed", "seconds": 28800 },
          "startTrigger": { "type": "afterStep", "stepId": "streak-purity-plate" }
        }
      ]
    },
    {
      "trackId": "t-stain",
      "name": "Gram stain and microscopy",
      "steps": [
        {
          "stepId": "smear-heatfix",
          "name": "Make a smear from the picked colony and heat-fix it",
          "task": "bench",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "afterStep", "stepId": "pick-colony", "instances": "all" }
        },
        {
          "stepId": "gram-stain",
          "name": "Gram stain on the rack: crystal violet, iodine, decolourise, safranin",
          "task": "stainingRack",
          "duration": { "type": "fixed", "seconds": 900 },
          "startTrigger": { "type": "afterStep", "stepId": "smear-heatfix" }
        },
        {
          "stepId": "microscope-read",
          "name": "Read the stain under oil immersion and record the morphology",
          "task": "microscope",
          "duration": { "type": "fixed", "seconds": 900 },
          "startTrigger": { "type": "afterStep", "stepId": "gram-stain" }
        }
      ]
    }
  ],
  "resourceConstraints": [
    { "task": "bench", "maxConcurrent": 1 },
    { "task": "loopStation", "maxConcurrent": 1 },
    { "task": "incubator", "maxConcurrent": 2 },
    { "task": "supervisor", "maxConcurrent": 1 },
    { "task": "stainingRack", "maxConcurrent": 1 },
    { "task": "microscope", "maxConcurrent": 1 }
  ],
  "metadata": {
    "sourceUrl": "",
    "attribution": "",
    "notes": "One loop station at the burner (loopStation maxConcurrent 1) chains the three streaks and the purity-plate streak; the incubator shelf holds two plates, enforced both as maxConcurrent 2 on the incubator and as maxInFlight 2 on the replicated incubation so plate 3 waits on the bench until plate 1 leaves the shelf. Purity plating is gated on the supervisor's sign-off of the readings."
  }
}
```
